            for(y=2;y<H-2;y+=2)for(x=2;x<W-2;x+=2)if(Math.random()<.72){grid[y][x]=1;if(Math.random()<.5&&x+1<W-1)grid[y][x+1]=1;else if(y+1<H-1)grid[y+1][x]=1;}
            for(x=1;x<W-1;x++)grid[1][x]=0;for(y=1;y<H-1;y++)grid[y][1]=0;
            var stars=[],free=[];
            for(y=1;y<H-1;y++)for(x=1;x<W-1;x++)if(!grid[y][x]&&(x!==1||y!==1))free.push({x:x,y:y});
            free=shuffle(free);var target=Math.min(28,12+Math.floor(lv*.7));for(var i=0;i<Math.min(target,free.length);i++)stars.push(free[i]);
            var enemies=[],ec=Math.min(4,1+Math.floor((lv-1)/6));for(var e=0;e<ec;e++){var q=free[target+e]||{x:W-2-e,y:H-2};enemies.push({x:q.x,y:q.y,phase:Math.random()*6});}
            game={kind:'chase',grid:grid,w:W,h:H,px:1,py:1,stars:stars,enemies:enemies,collected:0,target:stars.length,lives:3,level:lv,score:0,over:false};
            say('Збери всі зірки й не дай бешкетникам тебе наздогнати!');
