                for(var d=0;d<dirs.length;d++){var nx=e.x+dirs[d][0],ny=e.y+dirs[d][1];if(!chaseBlocked(nx,ny))opts.push({x:nx,y:ny,dist:Math.abs(nx-game.px)+Math.abs(ny-game.py)});}
                if(!opts.length)continue;
